# Load all grids (demos and test input)
import os, re

def load():
    d = os.environ.get('RLM_SESSION_DIR')
    if not d:
        return {}
    session_name = os.path.basename(d)
    path = os.path.join(os.path.dirname(d), '..', 'sessions', session_name + '.jsonl')
    try:
        text = open(path).read()
    except:
        return {}

    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, text):
        key, h, w = m[1], int(m[2]), int(m[3])
        # Find the grid rows after this marker
        end = m.end()
        lines = []
        for i in range(h):
            line_start = end + 8 * i
            if line_start + 30 <= len(text):
                row_str = text[line_start:line_start+30]
                lines.append(row_str.split())

        # Actually let's just read until we hit another section or blank enough lines
        start = m.end()
        rest = text[start:start+5000]  # sample limit
        lines = [line.split() for line in rest.strip().split('\n')]

        valid_rows = []
        for line in lines:
            if line and all(x.isdigit() for x in line):
                valid_rows.append([int(x) for x in line])
            elif valid_rows and len(valid_rows) >= h:
                break

        if len(valid_rows) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in valid_rows):
            G[key] = [[int(x) for x in r] for r in valid_rows]

    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
