# Test hypothesis: fill connected region of 1s with marker value
def flood_fill_region(grid, start_r, start_c):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    stack = [(start_r, start_c)]
    while stack:
        r, c = stack.pop()
        if (r,c) in visited or grid[r][c] == 0:
            continue
        visited.add((r,c))
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1 and (nr,nc) not in visited:
                stack.append((nr, nc))
    return visited

