def get_connected_component(grid, start_r, start_c):
    comp = set()
    stack = [(start_r, start_c)]
    while stack:
        r, c = stack.pop()
        if (r, c) not in comp and 0 <= r < len(grid) and 0 <= c < len(grid[0]):
            comp.add((r, c))
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r+dr, c+dc
                if (nr, nc) not in comp and 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] != 0:
                    stack.append((nr, nc))
    return comp

def lpath_reachable(r, c, target_r, target_c, grid):
    # Horizontal first, then vertical
    h_then_v = True
    for cc in range(min(c, target_c), max(c, target_c)+1):
        if grid[r][cc] == 0:
            h_then_v = False
            break
    for rr in range(min(r, target_r), max(r, target_r)+1):
        if grid[rr][target_c] == 0:
            h_then_v = False
            break

    # Vertical first, then horizontal  
    v_then_h = True
    for rr in range(min(r, target_r), max(r, target_r)+1):
        if grid[rr][c] == 0:
            v_then_h = False
            break
    for cc in range(min(c, target_c), max(c, target_c)+1):
        if grid[target_r][cc] == 0:
            v_then_h = False
            break

    return h_then_v or v_then_h

