def neighbors_along_path_direction(r, c, target_r, target_c):
    """Return set of neighbors whose coordinate changes toward target"""
    dir_r, dir_c = 0, 0
    if r < target_r: dir_r = -1  # Need to go up
    elif r > target_r: dir_r = 1
    if c < target_c: dir_c = -1  # Need to go left
    elif c > target_c: dir_c = 1

    result = []
    for dr, dc in [(dir_r, 0), (0, dir_c)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 30 and 0 <= nc < 30:
            if dr != 0 and dc == 0:
                result.append((nr, nc))  # Up/down neighbor
            elif dr == 0 and dc != 0:
                result.append((nr, nc))  # Left/right neighbor
    return result

